"""Generate the catalogue-only subset of the existing development seed; no credentials or network."""
import json
from pathlib import Path
from seed_development import dataset, PROJECT

if __name__ == "__main__":
    fixtures = json.dumps(dataset()["fixtures"], ensure_ascii=True, separators=(",", ":"))
    sql = f"""-- Catalogue-only TEST data for approved development project {PROJECT}.
-- Generated by scripts/prepare-catalogue-seed.py. Existing records are never overwritten.
-- No Auth accounts, availability, bookings, reviews or payments are created.
begin;
select pg_advisory_xact_lock(hashtextextended('eventrahq-development-seed-v1',0));
create temporary table eventra_catalogue_seed on commit drop as
select * from jsonb_to_recordset($fixtures${fixtures}$fixtures$::jsonb)
as f(id uuid,slug text,name text,category text,city text,price_paise bigint,tags text[],tagline text,description text,event_types text[]);
do $guard$
begin
 if (select count(*) from eventra_catalogue_seed) <> 120 then raise exception 'Unexpected fixture count'; end if;
 if exists(select 1 from app.artists a join eventra_catalogue_seed s on a.slug=s.slug or a.id=s.id
   where a.id<>s.id or a.slug<>s.slug or not a.is_fixture or a.owner_id is not null) then
   raise exception 'Catalogue seed conflicts with an existing artist; no records changed';
 end if;
end;
$guard$;
with inserted as (
 insert into app.artists(id,slug,name,category,city,price_paise,tags,tagline,description,event_types,status,is_fixture,available,rating,review_count)
 select id,slug,name,category,city,price_paise,tags,tagline,description,event_types,'published',true,false,0,0 from eventra_catalogue_seed
 on conflict(id) do nothing returning id
)
select count(*) as inserted_fixture_artists from inserted;
commit;
"""
    target = Path(__file__).with_name("seed-catalogue.sql")
    target.write_text(sql, encoding="utf-8")
    print(f"Prepared 120 catalogue fixtures for {PROJECT}; no remote changes.")
